#!/bin/bash
# Compile conch Microphone, conch's native recorder, for one architecture.
#
#   scripts/build-microphone.sh <arm64|x86_64> <output>
#
# The source is seashell's recorder (mac-app/helpers/microphone/, generated by
# scripts/sync-microphone.sh), compiled the way seashell compiles it
# (seashell scripts/build-native.sh): one swiftc call, AVFoundation and
# CoreAudio, the Info.plist embedded in __TEXT,__info_plist so macOS has a name
# and a usage string to ask for the Microphone with, and a fixed module name so
# the same source gives the same bytes. It is not signed here: the Xcode phase
# (scripts/embed-microphone.sh) signs it like the app.
#
# Test seam: SWIFTC (default `xcrun swiftc`).
set -euo pipefail

ARCH="${1:?usage: scripts/build-microphone.sh <arm64|x86_64> <output>}"
OUT="${2:?usage: scripts/build-microphone.sh <arm64|x86_64> <output>}"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SOURCE_DIR="$REPO_ROOT/mac-app/helpers/microphone"
# The app's own minimum (MACOSX_DEPLOYMENT_TARGET), so the helper runs wherever conch.app does.
MIN_MACOS=14.0

case "$ARCH" in
  arm64 | x86_64) ;;
  *) echo "error: no conch Microphone recipe for $ARCH" >&2; exit 1 ;;
esac

# shellcheck disable=SC2206
swiftc=(${SWIFTC:-xcrun swiftc})
mkdir -p "$(dirname "$OUT")"
"${swiftc[@]}" "$SOURCE_DIR/conch-microphone.swift" -O -module-name ConchMicrophone \
  -target "$ARCH-apple-macos$MIN_MACOS" \
  -framework AVFoundation -framework CoreAudio \
  -Xlinker -sectcreate -Xlinker __TEXT -Xlinker __info_plist -Xlinker "$SOURCE_DIR/Info.plist" \
  -o "$OUT"
